argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$expectedHead='e8033f2e42bd335c10a397eb3d2cb62c8bb837a9';
$manifest='E:\WebAIBridge\app\data\backups\r42-cutover-20261006T043453Z\rollback-manifest.json';
$allowed=@('app/scripts/operator-lifecycle-r40.ps1','app/scripts/pause-all-r40.cmd','app/scripts/pause-browser-r40.cmd','app/scripts/resume-attach-r40.cmd','app/scripts/resume-managed-r40.cmd');
Push-Location $repo;
$head=([string](git rev-parse HEAD)).Trim();
if($head -ne $expectedHead){ throw "unexpected current head before rollback: $head" }
$status=@(git status --porcelain);
$paths=@($status | ForEach-Object { ($_ -replace '^.. ','').Trim() });
$extra=@($paths | Where-Object { $_ -notin $allowed });
$missing=@($allowed | Where-Object { $_ -notin $paths });
if($extra.Count -gt 0){ throw "unexpected dirty paths: $($extra -join ', ')" }
if($missing.Count -gt 0){ throw "expected generated dirty paths missing: $($missing -join ', ')" }
& git restore --source=HEAD --worktree -- @allowed;
if($LASTEXITCODE -ne 0){ throw "git restore generated wrappers failed" }
$after=@(git status --porcelain);
if($after.Count -ne 0){ throw "worktree still dirty before rollback: $($after -join '; ')" }
Pop-Location;
if(!(Test-Path $manifest)){ throw "rollback manifest missing: $manifest" }
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File 'E:\WebAIBridge\app\r42-rollback.ps1' -Manifest $manifest;
if($LASTEXITCODE -ne 0){ throw "R42 rollback failed with exit $LASTEXITCODE" }
Push-Location $repo;
$restored=([string](git rev-parse HEAD)).Trim();
$restoredDirty=@(git status --porcelain);
Pop-Location;
$statusApi=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/status' -TimeoutSec 5;
[pscustomobject]@{
  restoredHead=$restored;
  dirtyCount=$restoredDirty.Count;
  bridgeResponsive=$true;
  serverStartedAt=$statusApi.serverStartedAt;
  rollbackManifest=$manifest
}|ConvertTo-Json -Compress
